def is_balanced(s: str) -> bool:
    count = 0
    for ch in s:
        if ch == '<':
            count += 1
        elif ch == '>':
            count -= 1
        else:
            # ignore any other characters
            continue
        if count < 0:
            return False
    return count == 0
